887	    function cl_fix_to_integer(a : std_logic_vector; aFmt : FixFormat_t) return integer is
888	        -- Force downto 0
889	        constant a_c    : std_logic_vector(a'length-1 downto 0) := a;
890	    begin
891	        -- Modelsim throws warnings if to_integer() is called on 1-bit signed or any 0-bit input.
892	        -- We handle these special cases explicitly to avoid the warnings.
893	        if cl_fix_width(aFmt) = 0 then
894	            return 0;
895	        elsif aFmt.S = 1 and cl_fix_width(aFmt) = 1 then
896	            if a_c(0) = '1' then
897	                -- Note: -1 in the integer representation is -2**aFmt.I in fixed point.
898	                return -1;
899	            else
900	                return 0;
901	            end if;
902	        end if;
903	        
904	        -- Normal cases
905	        if aFmt.S = 1 then
906	            return to_integer(signed(a_c));
907	        else
908	            return to_integer(unsigned(a_c));
909	        end if;
910	    end function;
