592	                -- cl_fix_in_range
593	                print("cl_fix_in_range");
594	                check_equal(cl_fix_in_range(cl_fix_from_real(1.25, (1, 4, 2)), (1, 4, 2),
595	                                            (1, 2, 4), Trunc_s),
596	                            true,
597	                            "In Range Normal");
598	                check_equal(cl_fix_in_range(cl_fix_from_real(6.25, (1, 4, 2)), (1, 4, 2),
599	                                            (1, 2, 4), Trunc_s),
600	                            false,
601	                            "Out Range Normal");
602	                check_equal(cl_fix_in_range(cl_fix_from_real(-1.25, (1, 4, 2)), (1, 4, 2),
603	                                            (0, 5, 2), Trunc_s),
604	                            false,
605	                            "signed -> unsigned OOR");
606	                check_equal(cl_fix_in_range(cl_fix_from_real(15.0, (0, 4, 2)), (0, 4, 2),
607	                                            (1, 3, 2), Trunc_s),
608	                            false,
609	                            "unsigned -> signed OOR");
610	                check_equal(cl_fix_in_range(cl_fix_from_real(15.0, (0, 4, 2)), (0, 4, 2),
611	                                            (1, 4, 2), Trunc_s),
612	                            true,
613	                            "unsigned -> signed OK");
614	                check_equal(cl_fix_in_range(cl_fix_from_real(15.5, (0, 4, 2)), (0, 4, 2),
615	                                            (1, 4, 0), NonSymPos_s),
616	                            false,
617	                            "rounding OOR");
618	                check_equal(cl_fix_in_range(cl_fix_from_real(15.5, (0, 4, 2)), (0, 4, 2),
619	                                            (1, 4, 1), NonSymPos_s),
620	                            true,
621	                            "rounding OK 1");
622	                check_equal(cl_fix_in_range(cl_fix_from_real(15.5, (0, 4, 2)), (0, 4, 2),
623	                                            (0, 5, 0), NonSymPos_s),
624	                            true,
625	                            "rounding OK 2");
626	                
627	                -- cl_fix_compare
628	                print("cl_fix_compare");
629	                check_equal(cl_fix_compare("<",
630	                                            cl_fix_from_real(1.25, (0, 4, 2)), (0, 4, 2),
631	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
632	                            true,
633	                            "a<b unsigned unsigned true");
634	                check_equal(cl_fix_compare("<",
635	                                            cl_fix_from_real(1.5, (0, 4, 2)), (0, 4, 2),
636	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
637	                            false,
638	                            "a<b unsigned unsigned false");
639	                check_equal(cl_fix_compare("<",
640	                                            cl_fix_from_real(1.25, (1, 4, 2)), (1, 4, 2),
641	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
642	                            true,
643	                            "a<b signed unsigned true");
644	                check_equal(cl_fix_compare("<",
645	                                            cl_fix_from_real(2.5, (0, 4, 2)), (0, 4, 2),
646	                                            cl_fix_from_real(1.5, (1, 2, 1)), (1, 2, 1)),
647	                            false,
648	                            "a<b unsigned signed false");
649	                check_equal(cl_fix_compare("<",
650	                                            cl_fix_from_real(-1.25, (1, 4, 2)), (1, 4, 2),
651	                                            cl_fix_from_real(-1.0, (1, 2, 1)), (1, 2, 1)),
652	                            true,
653	                            "a<b signed signed true");
654	                check_equal(cl_fix_compare("<",
655	                                            cl_fix_from_real(-0.5, (1, 4, 2)), (1, 4, 2),
656	                                            cl_fix_from_real(-1.5, (1, 2, 1)), (1, 2, 1)),
657	                            false,
658	                            "a<b signed signed false");
659	                                
660	                check_equal(cl_fix_compare("=",
661	                                            cl_fix_from_real(1.5, (1, 4, 2)), (1, 4, 2),
662	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
663	                            true,
664	                            "a=b signed unsigned true");
665	                check_equal(cl_fix_compare("=",
666	                                            cl_fix_from_real(2.5, (0, 4, 2)), (0, 4, 2),
667	                                            cl_fix_from_real(-1.5, (1, 2, 1)), (1, 2, 1)),
668	                            false,
669	                            "a=b unsigned signed false");
670	                                
671	                check_equal(cl_fix_compare(">",
672	                                            cl_fix_from_real(2.5, (1, 4, 2)), (1, 4, 2),
673	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
674	                            true,
675	                            "a>b signed unsigned true");
676	                check_equal(cl_fix_compare(">",
677	                                            cl_fix_from_real(1.5, (0, 4, 2)), (0, 4, 2),
678	                                            cl_fix_from_real(1.5, (1, 2, 1)), (1, 2, 1)),
679	                            false,
680	                            "a>b unsigned signed false");
681	                                
682	                check_equal(cl_fix_compare(">=",
683	                                            cl_fix_from_real(2.5, (1, 4, 2)), (1, 4, 2),
684	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
685	                            true,
686	                            "a>=b signed unsigned true 1");
687	                check_equal(cl_fix_compare(">=",
688	                                            cl_fix_from_real(1.5, (1, 4, 2)), (1, 4, 2),
689	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
690	                            true,
691	                            "a>=b signed unsigned true 2");
692	                check_equal(cl_fix_compare(">=",
693	                                            cl_fix_from_real(1.25, (0, 4, 2)), (0, 4, 2),
694	                                            cl_fix_from_real(1.5, (1, 2, 1)), (1, 2, 1)),
695	                            false,
696	                            "a>=b unsigned signed false 1");
697	                                
698	                check_equal(cl_fix_compare("<=",
699	                                            cl_fix_from_real(-2.5, (1, 4, 2)), (1, 4, 2),
700	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
701	                            true,
702	                            "a<=b signed unsigned true 1");
703	                check_equal(cl_fix_compare("<=",
704	                                            cl_fix_from_real(1.5, (1, 4, 2)), (1, 4, 2),
705	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
706	                            true,
707	                            "a<=b signed unsigned true 2");
708	                check_equal(cl_fix_compare("<=",
709	                                            cl_fix_from_real(0.25, (0, 4, 2)), (0, 4, 2),
710	                                            cl_fix_from_real(-1.5, (1, 2, 1)), (1, 2, 1)),
711	                            false,
712	                            "a<=b unsigned signed false 1");
713	                                
714	                check_equal(cl_fix_compare("!=",
715	                                            cl_fix_from_real(1.5, (1, 4, 2)), (1, 4, 2),
716	                                            cl_fix_from_real(1.5, (0, 2, 1)), (0, 2, 1)),
717	                            false,
718	                            "a!=b signed unsigned false");
719	                check_equal(cl_fix_compare("!=",
720	                                            cl_fix_from_real(2.5, (0, 4, 2)), (0, 4, 2),
721	                                            cl_fix_from_real(-1.5, (1, 2, 1)), (1, 2, 1)),
722	                            true,
723	                            "a!=b unsigned signed true");
724	                            
725	                -- cl_fix_addsub
726	                print("cl_fix_addsub");
727	                check_equal(cl_fix_addsub(cl_fix_from_real(1.0, (1,3,3)), (1,3,3),
728	                                          cl_fix_from_real(0.75, (1,3,3)), (1,3,3), '1', (1,3,3)),
729	                            cl_fix_from_real(1.75, (1,3,3)),
730	                            "Add");
731	                check_equal(cl_fix_addsub(cl_fix_from_real(1.25, (1,3,3)), (1,3,3),
732	                                          cl_fix_from_real(0.25, (1,3,3)), (1,3,3), '0', (1,3,3)),
733	                            cl_fix_from_real(1.0, (1,3,3)),
734	                            "Sub");
735	            end if;
736	        end loop;
737	        
738	        print("SUCCESS! All tests passed.");
739	        test_runner_cleanup(runner);
740	        wait;
741	    end process;
742	    
743	end sim;
